     * screen's directory. See `core::people`.
     */
    fun `knownPeople`(): List<PersonDto>
    
    /**
     * Leave a room. It disappears from the roster on the next diff.
     */
    fun `leaveRoom`(`roomId`: kotlin.String)
    
    /**
