 * `&'static str`, which cannot cross an FFI boundary that has to own what it
 * carries.
 */
data class ConnectionState (
    /**
     * `"live"`, `"connecting"` or `"offline"` — the same vocabulary the
     * desktop app's connection indicator reads.
